def count_primes(n):
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
    return len(primes)

def legendre(n, p):
    count = 0
    i = p
    while i <= n:
        count += n // i
        i *= p
    return count

